package com.aicharacter.v3;
/** Converts regional impact/load into automatic guarding and load redistribution, never into dialogue or intention. */
public final class PainLocalizationEngine{private PainLocalizationEngine(){}
 public static void advance(WorldState s,double dt,long now){if(s==null||dt<=0)return;if(s.localizedPain==null)s.localizedPain=new LocalizedPainState();LocalizedPainState p=s.localizedPain;double base=s.body==null?0:s.body.pain/100.0,impact=s.musculoskeletal==null?0:Math.min(1,s.musculoskeletal.impactLoad/8.0);p.leftLeg=decayToward(p.leftLeg,base*.28+impact*.20,dt);p.rightLeg=decayToward(p.rightLeg,base*.28+impact*.20,dt);p.core=decayToward(p.core,base*.32+impact*.16,dt);p.leftArm=decayToward(p.leftArm,base*.18,dt);p.rightArm=decayToward(p.rightArm,base*.18,dt);p.head=decayToward(p.head,base*.12,dt);p.lastUpdatedAt=Math.max(p.lastUpdatedAt,now);}
 public static void addLandingImpact(WorldState s,double excess,double leftLoad,double rightLoad,double armLoad,double headLoad,long now){if(s.localizedPain==null)s.localizedPain=new LocalizedPainState();LocalizedPainState p=s.localizedPain;double q=Math.min(1,excess/900.0),sum=Math.max(.1,leftLoad+rightLoad);p.leftLeg=cl(p.leftLeg+q*.62*leftLoad/sum);p.rightLeg=cl(p.rightLeg+q*.62*rightLoad/sum);p.core=cl(p.core+q*.28);p.leftArm=cl(p.leftArm+q*.34*armLoad);p.rightArm=cl(p.rightArm+q*.34*armLoad);p.head=cl(p.head+q*.30*headLoad);p.lastUpdatedAt=Math.max(p.lastUpdatedAt,now);}
 private static double decayToward(double v,double floor,double dt){return cl(Math.max(floor,v));}private static double cl(double v){return Math.max(0,Math.min(1,v));}}
